CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"e0395cad-ee0c-5471-8219-91f911e2c13c","source_id":"3543","name_en":"bodyweight drop jump squat","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0642\u0641\u0632\u0629 \u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645","match_names":["bodyweight drop jump squat"],"muscle":"glutes","equipment":"bodyweight","aliases":["bodyweight drop jump squat"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart.\nLower your body into a squat position by bending your knees and pushing your hips back.\nJump up explosively, extending your hips, knees, and ankles.\nWhile in mid-air, quickly bring your feet together.\nLand softly on the balls of your feet and immediately drop back into a squat position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062f\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641.\n\u0627\u0642\u0641\u0632 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u0631\u0643\u0628\u062a\u064a\u0646 \u0648\u0627\u0644\u0643\u0627\u062d\u0644\u064a\u0646.\n\u0623\u062b\u0646\u0627\u0621 \u0648\u062c\u0648\u062f\u0643 \u0641\u064a \u0627\u0644\u0647\u0648\u0627\u0621\u060c \u0642\u0645 \u0628\u0636\u0645 \u0642\u062f\u0645\u064a\u0643 \u0628\u0633\u0631\u0639\u0629.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u062b\u0645 \u0627\u0631\u062c\u0639 \u0641\u0648\u0631\u064b\u0627 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3543","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["quadriceps","hamstrings","calves"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3543-wfotm7S.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3543-wfotm7S.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7dc3fef3-35c7-5129-8a8b-5d53eb7f8271","source_id":"3544","name_en":"bodyweight incline side plank","name_ar":"\u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062c\u0627\u0646\u0628\u064a \u0627\u0644\u0645\u0627\u0626\u0644 \u0644\u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645","match_names":["bodyweight incline side plank"],"muscle":"core","equipment":"bodyweight","aliases":["bodyweight incline side plank"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Start by lying on your side with your legs extended and stacked on top of each other.\nPlace your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.\nEngage your core and lift your hips off the ground, creating a straight line from your head to your feet.\nHold this position for the desired amount of time.\nLower your hips back down to the ground and repeat on the other side.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0627\u0644\u0627\u0633\u062a\u0644\u0642\u0627\u0621 \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u0645\u0643\u062f\u0633\u062a\u064a\u0646 \u0641\u0648\u0642 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u0636\u0639 \u0633\u0627\u0639\u062f\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0633\u0641\u0644 \u0643\u062a\u0641\u0643 \u0645\u0628\u0627\u0634\u0631\u0629\u060c \u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u0643 \u0628\u0632\u0627\u0648\u064a\u0629 90 \u062f\u0631\u062c\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u0627\u0631\u0641\u0639 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0645\u0627 \u064a\u062e\u0644\u0642 \u062e\u0637\u064b\u0627 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0645\u0646 \u0631\u0623\u0633\u0643 \u0625\u0644\u0649 \u0642\u062f\u0645\u064a\u0643.\n\u0634\u063a\u0644 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u0635\u0628 \u0644\u0644\u0645\u062f\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629 \u0645\u0646 \u0627\u0644\u0648\u0642\u062a.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3544","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["obliques","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3544-5VXmnV5.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3544-5VXmnV5.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"12a66bc3-c415-5399-8ca7-e0cbfd7867cc","source_id":"1771","name_en":"bodyweight kneeling triceps extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0639\u0636\u0644\u0629 \u062b\u0644\u0627\u062b\u064a\u0629 \u0627\u0644\u0631\u0624\u0648\u0633 \u0641\u064a \u0627\u0644\u0631\u0643\u0648\u0639 \u0628\u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645","match_names":["bodyweight kneeling triceps extension"],"muscle":"triceps","equipment":"bodyweight","aliases":["bodyweight kneeling triceps extension"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Kneel down on the ground with your knees hip-width apart.\nPlace your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.\nExtend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.\nBend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.\nPause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0631\u0643\u0639 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0645\u0641\u0635\u0644 \u0627\u0644\u0648\u0631\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636 \u0623\u0645\u0627\u0645\u0643\u060c \u0645\u062a\u0628\u0627\u0639\u062f\u062a\u064a\u0646 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0623\u0635\u0627\u0628\u0639 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0645\u0628\u0627\u0634\u0631\u0629 \u062e\u0644\u0641\u0643\u060c \u0645\u0639 \u0627\u0644\u0645\u0648\u0627\u0632\u0646\u0629 \u0628\u064a\u0646 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0648\u064a\u062f\u064a\u0643\u060c \u0648\u062a\u0634\u0643\u064a\u0644 \u062e\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0645\u0646 \u0627\u0644\u0631\u0623\u0633 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0648\u062e\u0641\u0636 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0628\u064a\u062f\u064a\u0643 \u0644\u0641\u0631\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0648\u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1771","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["shoulders","chest"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1771-s0HKO2I.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1771-s0HKO2I.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2ab6c6c8-093a-5a9e-8c62-a01b46e04512","source_id":"1769","name_en":"bodyweight side lying biceps curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \u0627\u0644\u0631\u0623\u0633\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0629 \u0645\u0646 \u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645","match_names":["bodyweight side lying biceps curl"],"muscle":"biceps","equipment":"bodyweight","aliases":["bodyweight side lying biceps curl"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Lie on your side with your legs extended and your head supported by your arm.\nHold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.\nPause for a moment at the top, then slowly lower your forearm back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643 \u0648\u062f\u0639\u0645 \u0631\u0623\u0633\u0643 \u0628\u0630\u0631\u0627\u0639\u0643.\n\u0623\u0645\u0633\u0643 \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u0639\u0644\u0648\u064a \u0639\u0644\u0649 \u062c\u0627\u0646\u0628\u0643 \u0648\u0627\u062b\u0646\u0650 \u0645\u0631\u0641\u0642\u0643 \u0644\u062a\u062c\u0639\u064a\u062f \u0633\u0627\u0639\u062f\u0643 \u0646\u062d\u0648 \u0643\u062a\u0641\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0639\u062f\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1769","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"biceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1769-gscGLOU.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1769-gscGLOU.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"2a02a6d3-5d58-524a-8b00-21a12b727134","source_id":"3168","name_en":"bodyweight squatting row","name_ar":"\u0635\u0641 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645","match_names":["bodyweight squatting row"],"muscle":"back","equipment":"bodyweight","aliases":["bodyweight squatting row"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding onto a sturdy object or suspension trainer with your arms extended.\nLower your body into a squat position, keeping your back straight and your knees behind your toes.\nFrom the squat position, pull your body up towards the object or suspension trainer, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u062c\u0633\u0645 \u0642\u0648\u064a \u0623\u0648 \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627\u064b \u0648\u0631\u0643\u0628\u062a\u064a\u0643 \u062e\u0644\u0641 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643.\n\u0645\u0646 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u062c\u0633\u0645 \u0623\u0648 \u0645\u062f\u0631\u0628 \u0627\u0644\u062a\u0639\u0644\u064a\u0642\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3168","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3168-3xK09Sk.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3168-3xK09Sk.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"f1944b70-4932-53d2-8114-6b5e0848df22","source_id":"3167","name_en":"bodyweight squatting row (with towel)","name_ar":"\u0635\u0641 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645 (\u0645\u0639 \u0627\u0644\u0645\u0646\u0634\u0641\u0629)","match_names":["bodyweight squatting row (with towel)"],"muscle":"back","equipment":"bodyweight","aliases":["bodyweight squatting row (with towel)"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, holding a towel in front of you with your palms facing down.\nBend your knees and lower your body into a squat position, keeping your back straight and your chest up.\nAs you lower into the squat, simultaneously pull the towel towards your chest, squeezing your shoulder blades together.\nPause for a moment at the bottom of the squat, then slowly return to the starting position while extending your arms.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u0623\u0645\u0633\u0643 \u0628\u0645\u0646\u0634\u0641\u0629 \u0623\u0645\u0627\u0645\u0643 \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0633\u0641\u0644.\n\u0642\u0645 \u0628\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u062e\u0641\u0636 \u062c\u0633\u0645\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0623\u062b\u0646\u0627\u0621 \u0646\u0632\u0648\u0644\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0646\u0634\u0641\u0629 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0645\u0639 \u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3167","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3167-BReCuOn.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3167-BReCuOn.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"135f973a-2bcc-5230-8208-e89eb4721ec4","source_id":"1373","name_en":"bodyweight standing calf raise","name_ar":"\u0631\u0641\u0639 \u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645 \u0648\u0627\u0642\u0641\u0627\u064b","match_names":["bodyweight standing calf raise"],"muscle":"calves","equipment":"bodyweight","aliases":["bodyweight standing calf raise"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, toes pointing forward.\nPlace your hands on a wall or stable surface for balance.\nSlowly raise your heels off the ground, lifting your body weight onto the balls of your feet.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062a\u0648\u062c\u064a\u0647 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0644\u0644\u0623\u0645\u0627\u0645.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0626\u0637 \u0623\u0648 \u0639\u0644\u0649 \u0633\u0637\u062d \u062b\u0627\u0628\u062a \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062a\u0648\u0627\u0632\u0646.\n\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0627\u0631\u0641\u0639\u064a \u0648\u0632\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1373","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["ankles","feet"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1373-bJYHBIN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1373-bJYHBIN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e16dae37-b0c6-5ef8-88e2-e1ba152def79","source_id":"3156","name_en":"bodyweight standing close-grip one arm row","name_ar":"\u0648\u0632\u0646 \u0627\u0644\u062c\u0633\u0645 \u064a\u0642\u0641 \u0628\u0642\u0628\u0636\u0629 \u0642\u0631\u064a\u0628\u0629 \u0639\u0644\u0649 \u0635\u0641 \u0630\u0631\u0627\u0639 \u0648\u0627\u062d\u062f","match_names":["bodyweight standing close-grip one arm row"],"muscle":"back","equipment":"bodyweight","aliases":["bodyweight standing close-grip one arm row"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart, knees slightly bent, and hold a dumbbell in one hand with a neutral grip.\nBend forward at the hips, keeping your back straight and your core engaged.\nPull the dumbbell up towards your chest, keeping your elbow close to your body and squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower the dumbbell back down to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646\u060c \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0648\u0627\u0645\u0633\u0643 \u0627\u0644\u062f\u0645\u0628\u0644 \u0641\u064a \u064a\u062f \u0648\u0627\u062d\u062f\u0629 \u0628\u0642\u0628\u0636\u0629 \u0645\u062d\u0627\u064a\u062f\u0629.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u062f\u0645\u0628\u0644 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0648\u0639\u0643 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u062c\u0633\u0645\u0643 \u0648\u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u064a\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0627\u0644\u062f\u0645\u0628\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3156","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3156-v2DfH14.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3156-v2DfH14