-NvfE43H.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"9dc9ecfb-b18e-53df-81c1-6c38b257eb2a","source_id":"0152","name_en":"cable concentration extension (on knee)","name_ar":"\u062a\u0645\u062f\u064a\u062f \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 (\u0639\u0644\u0649 \u0627\u0644\u0631\u0643\u0628\u0629)","match_names":["cable concentration extension (on knee)"],"muscle":"triceps","equipment":"cable","aliases":["cable concentration extension (on knee)"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Sit on a bench or chair with your knees bent and feet flat on the ground.\nHold the cable handle with your right hand and place your elbow on the inside of your right knee.\nExtend your arm fully, keeping your elbow stationary and close to your knee.\nPause for a moment at the top, then slowly lower your arm back to the starting position.\nRepeat for the desired number of repetitions, then switch sides.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0623\u0648 \u0643\u0631\u0633\u064a \u0645\u0639 \u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u0636.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0648\u0636\u0639 \u0645\u0631\u0641\u0642\u0643 \u0639\u0644\u0649 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0645\u0646 \u0631\u0643\u0628\u062a\u0643 \u0627\u0644\u064a\u0645\u0646\u0649.\n\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u0643 \u062b\u0627\u0628\u062a\u064b\u0627 \u0648\u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0631\u0643\u0628\u062a\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0630\u0631\u0627\u0639\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0630\u0644\u0643 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a\u060c \u062b\u0645 \u0628\u062f\u0644 \u0627\u0644\u062c\u0648\u0627\u0646\u0628.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0152","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"triceps","secondary_muscles":["forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0152-Db7eEgw.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0152-Db7eEgw.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"61803c97-072d-56e9-854f-5e8c5145779c","source_id":"0153","name_en":"cable cross-over lateral pulldown","name_ar":"\u0643\u0627\u0628\u0644 \u0639\u0628\u0631 \u0627\u0644\u0645\u0646\u0633\u062f\u0644\u0629 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0629","match_names":["cable cross-over lateral pulldown"],"muscle":"back","equipment":"cable","aliases":["cable cross-over lateral pulldown"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a cable handle to each side of a cable machine at shoulder height.\nStand in the middle of the machine with your feet shoulder-width apart.\nGrasp the handles with an overhand grip and step back to create tension in the cables.\nLean forward slightly from the hips, keeping your back straight and your chest up.\nPull the handles down and across your body, squeezing your shoulder blades together.\nPause for a moment at the bottom of the movement, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0644\u0649 \u0643\u0644 \u062c\u0627\u0646\u0628 \u0645\u0646 \u062c\u0648\u0627\u0646\u0628 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0646\u062f \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0643\u062a\u0641.\n\u0642\u0641 \u0641\u064a \u0645\u0646\u062a\u0635\u0641 \u0627\u0644\u0622\u0644\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0648\u062a\u0631\u0627\u062c\u0639 \u0625\u0644\u0649 \u0627\u0644\u062e\u0644\u0641 \u0644\u062e\u0644\u0642 \u062a\u0648\u062a\u0631 \u0641\u064a \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a.\n\u0627\u0646\u062d\u0646\u064a \u0644\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638\u064a \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u0639\u0628\u0631 \u062c\u0633\u0645\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0627\u062a \u0623\u0633\u0641\u0644 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0153","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","rhomboids","rear deltoids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0153-OQ1otBN.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0153-OQ1otBN.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b11c8932-c93b-5303-8f1e-fd782094d2ca","source_id":"0154","name_en":"cable cross-over revers fly","name_ar":"\u064a\u0637\u064a\u0631 \u0639\u0643\u0633 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u0645\u062a\u0642\u0627\u0637\u0639","match_names":["cable cross-over revers fly"],"muscle":"shoulders","equipment":"cable","aliases":["cable cross-over revers fly"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Attach a D-handle to each low pulley cable and stand in the middle of the cable crossover machine.\nGrasp the handles with a pronated grip (palms facing down) and take a step forward, positioning your feet shoulder-width apart.\nBend your knees slightly and lean forward at the waist, keeping your back straight and your abs engaged.\nWith your arms extended out to the sides and slightly bent at the elbows, exhale and squeeze your shoulder blades together as you pull the cables back and upward in a reverse fly motion.\nPause for a moment at the peak contraction, then inhale and slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0645\u0642\u0628\u0636 \u0639\u0644\u0649 \u0634\u0643\u0644 \u062d\u0631\u0641 D \u0628\u0643\u0644 \u0643\u0627\u0628\u0644 \u0628\u0643\u0631\u0629 \u0645\u0646\u062e\u0641\u0636\u0629 \u0648\u0642\u0641 \u0641\u064a \u0645\u0646\u062a\u0635\u0641 \u0622\u0644\u0629 \u062a\u0648\u0635\u064a\u0644 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0645\u0646\u0628\u0637\u062d\u0629 (\u0631\u0627\u062d\u0629 \u0627\u0644\u064a\u062f \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644) \u0648\u062e\u0637\u0648 \u062e\u0637\u0648\u0629 \u0644\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0641\u0629 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0648\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u062e\u0635\u0631\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643.\n\u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0648\u062b\u0646\u064a\u0647\u0645\u0627 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646\u062f \u0627\u0644\u0645\u0631\u0641\u0642\u064a\u0646\u060c \u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0623\u062b\u0646\u0627\u0621 \u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u0623\u0639\u0644\u0649 \u0641\u064a \u062d\u0631\u0643\u0629 \u0637\u064a\u0631\u0627\u0646 \u0639\u0643\u0633\u064a\u0629.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0630\u0631\u0648\u0629 \u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0154","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["rhomboids","trapezius"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0154-aqvSOQE.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0154-aqvSOQE.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7265df4c-774c-5539-8a08-68b6a1ee16ad","source_id":"0155","name_en":"cable cross-over variation","name_ar":"\u062a\u0628\u0627\u064a\u0646 \u0627\u0644\u0643\u0627\u0628\u0644\u0627\u062a \u0627\u0644\u0645\u062a\u0642\u0627\u0637\u0639\u0629","match_names":["cable cross-over variation"],"muscle":"chest","equipment":"cable","aliases":["cable cross-over variation"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the cable pulleys to chest height.\nStand in the center of the cable machine with one foot in front of the other.\nGrasp the handles with your palms facing down and your arms extended out to the sides.\nTake a step forward, keeping your arms slightly bent.\nWith a slight bend in your elbows, bring your hands together in front of your chest.\nPause for a moment, then slowly return your arms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0628\u0643\u0631\u0627\u062a \u0627\u0644\u0643\u0627\u0628\u0644 \u0639\u0644\u0649 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0635\u062f\u0631.\n\u0642\u0641 \u0641\u064a \u0648\u0633\u0637 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0648\u0636\u0639 \u0642\u062f\u0645 \u0648\u0627\u062d\u062f\u0629 \u0623\u0645\u0627\u0645 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0627\u062d\u0629 \u064a\u062f\u0643 \u0645\u062a\u062c\u0647\u0629 \u0644\u0644\u0623\u0633\u0641\u0644 \u0648\u062a\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0625\u0644\u0649 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646.\n\u062e\u0630 \u062e\u0637\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u062b\u0646\u064a\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0645\u0639 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b\u060c \u0627\u062c\u0645\u0639 \u064a\u062f\u064a\u0643 \u0645\u0639\u064b\u0627 \u0623\u0645\u0627\u0645 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0623\u0639\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0155","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["deltoids","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0155-0CXGHya.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0155-0CXGHya.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"749f748d-9c56-56d5-8131-2863b51e138c","source_id":"0868","name_en":"cable curl","name_ar":"\u062d\u0644\u064a\u0642\u0629 \u0627\u0644\u0643\u0627\u0628\u0644","match_names":["cable curl"],"muscle":"biceps","equipment":"cable","aliases":["cable curl"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand facing the cable machine with your feet shoulder-width apart.\nGrasp the cable attachment with an underhand grip, palms facing up.\nKeep your elbows close to your sides and your upper arms stationary.\nExhale and curl the cable attachment towards your shoulders, contracting your biceps.\nPause for a moment at the top of the movement, squeezing your biceps.\nInhale and slowly lower the cable attachment back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0641\u064a \u0645\u0648\u0627\u062c\u0647\u0629 \u062c\u0647\u0627\u0632 \u0627\u0644\u0643\u0627\u0628\u0644 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0645\u0631\u0641\u0642 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0623\u0639\u0644\u0649.\n\u0623\u0628\u0642\u0650 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0627\u0646\u0628\u064a\u0643 \u0648\u0630\u0631\u0627\u0639\u064a\u0643 \u0627\u0644\u0639\u0644\u0648\u064a\u064a\u0646 \u062b\u0627\u0628\u062a\u064a\u0646.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0642\u0645 \u0628\u0644\u0641 \u0627\u0644\u0643\u0627\u0628\u0644 \u0627\u0644\u0645\u0631\u0641\u0642 \u0646\u062d\u0648 \u0643\u062a\u0641\u064a\u0643\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u062a\u0642\u0644\u064a\u0635 \u0627\u0644\u0639\u0636\u0644\u0629 \u0630\u0627\u062a \