.\n\u0623\u0645\u0633\u0643 \u0628\u0645\u0631\u0641\u0642 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0639\u0631\u064a\u0636\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0625\u0644\u0649 \u0627\u0644\u0623\u0633\u0641\u0644.\n\u0627\u0646\u062d\u0646\u0650 \u0644\u0644\u062e\u0644\u0641 \u0642\u0644\u064a\u0644\u064b\u0627\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062c\u0630\u0628 \u062c\u0630\u0639\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0643\u0627\u0628\u0644 \u0646\u062d\u0648 \u0623\u0633\u0641\u0644 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0630\u0631\u0648\u0629 \u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634\u060c \u062b\u0645 \u062d\u0631\u0651\u0631 \u0627\u0644\u0643\u0627\u0628\u0644 \u0628\u0628\u0637\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0159","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4