ne.\nStand facing away from the machine with your feet shoulder-width apart.\nGrasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\nLean forward slightly and keep your back straight.\nPull the bar down towards your thighs by extending your elbows.\nPause for a moment at the bottom, then slowly return the bar to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0645 \u0628\u062a\u0648\u0635\u064a\u0644 \u0634\u0631\u064a\u0637 \u0645\u0633\u062a\u0642\u064a\u0645 \u0628\u0622\u0644\u0629 \u0643\u0627\u0628\u0644 \u0630\u0627\u062a \u0628\u0643\u0631\u0629 \u0639\u0627\u0644\u064a\u0629.\n\u0642\u0641 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0650 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0634\u0631\u064a\u0637 \u0644\u0623\u0633\u0641\u0644 \u0646\u062d\u0648 \u0641\u062e\u0630\u064a\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0645\u0631\u0641\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0623\u0639\u062f \u0627\u0644\u0634\u0631\u064a\u0637 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0172","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0172-1PK5Uo3.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0172-1PK5Uo3.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}}]'::jsonb)
AS r(id uuid,source_id text,name_en text,name_ar text,match_names jsonb,muscle text,equipment text,aliases jsonb,logging_mode text,load_convention text,guidance jsonb);
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM catalogue_input r WHERE (SELECT count(*) FROM public.exercises e WHERE
   (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
   OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment))>1)
 THEN RAISE EXCEPTION 'Ambiguous catalogue match; review before importing'; END IF;
END $$;
INSERT INTO public.exercises(id,name_en,name_ar,muscle,equipment,equipment_tags,aliases,logging_mode,load_convention,guidance,editorial_status)
SELECT coalesce((SELECT e.id FROM public.exercises e WHERE
  (e.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND e.guidance->'text_source'->>'exercise_id'=r.source_id)
  OR (e.guidance->'text_source' IS NULL AND lower(trim(e.name_en)) IN (SELECT lower(value) FROM jsonb_array_elements_text(r.match_names)) AND e.equipment=r.equipment)),r.id),
 r.name_en,r.name_ar,r.muscle,r.equipment,ARRAY[r.equipment],ARRAY(SELECT jsonb_array_elements_text(r.aliases)),r.logging_mode,r.load_convention,r.guidance,'needs_review'
FROM catalogue_input r
ON CONFLICT(id) DO UPDATE SET
 name_ar=coalesce(nullif(public.exercises.name_ar,''),EXCLUDED.name_ar),
 aliases=ARRAY(SELECT DISTINCT value FROM unnest(public.exercises.aliases || EXCLUDED.aliases) value ORDER BY value),
 guidance=EXCLUDED.guidance || public.exercises.guidance
WHERE public.exercises.editorial_status<>'reviewed'
 AND (public.exercises.guidance->'text_source' IS NULL OR
  (public.exercises.guidance->'text_source'->>'repository'='hasaneyldrm/exercises-dataset' AND public.exercises.guidance->'text_source'->>'exercise_id'=EXCLUDED.guidance->'text_source'->>'exercise_id'));
COMMIT;
